import json
from html import escape
from pathlib import Path

S = json.loads(Path('source.json').read_text())
R = json.loads(Path('reference-targets.json').read_text())
A = []

def add(i, paragraphs, reason, notes, removed=None, benefit=None):
    s = S[i]
    a = {k:s[k] for k in ('code_id','source_id','source_sha256','number')}
    a.update(proposed_xml=''.join('<p>'+escape(p, quote=False)+'</p>' for p in paragraphs),
             reason=reason, review_notes=notes, status='rewrite_draft')
    if removed:
        a.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    if benefit:
        a['benefit_review']=benefit
    A.append(a)

add(0, [
"Lorsqu'un redressement de cotisations ou de contributions sociales, ou une correction résultant des vérifications prévues à l'article L. 133-5-3-1, a une incidence sur les droits des salariés et assimilés aux assurances sociales ou à la retraite complémentaire légalement obligatoire, les organismes mentionnés aux articles L. 213-1 ou L. 752-4 du présent code ou à l'article L. 725-3 du code rural et de la pêche maritime transmettent les informations nécessaires à la correction de ces droits aux organismes figurant sur une liste arrêtée par le ministre chargé de la sécurité sociale. Un arrêté des ministres chargés du budget et de la sécurité sociale fixe la liste des informations transmissibles.",
"Les organismes destinataires réutilisent ces informations pour corriger les droits. Ils ne peuvent demander au salarié ou à l'employeur de déclarer ou de produire à nouveau les mêmes éléments exacts, à jour et légalement disponibles. Ils peuvent demander les seuls éléments manquants, modifiés ou contradictoires nécessaires à cette correction, dans le respect des secrets protégés et des règles de protection des données.",
"La dispense de nouvelle production s'applique aux demandes adressées à compter de l'entrée en vigueur de la loi qui l'institue, y compris lorsque le redressement ou la correction est antérieur. Elle ne modifie ni les droits à corriger ni les voies de recours."
], "Réécriture du déclencheur et des compétences à droit constant. Réforme de fond : la transmission interorganismes dispense effectivement les intéressés de reproduire les données déjà disponibles pour la même correction de droits.",
"Conserver les deux déclencheurs, les assurances sociales et la retraite complémentaire obligatoire, ainsi que les listes arrêtées. Coordonner les arrêtés d'échange et L133-5-3-1 avec la dispense, sans étendre les finalités des échanges. L213-1 proposé prévoit déjà le réemploi ; ce texte en tire l'effet pour la correction des droits. La note de 2025 ne date pas cette nouvelle réforme.",
["Nouvelle déclaration ou production des mêmes éléments déjà légalement transmis pour corriger les mêmes droits sociaux."])

add(1, [
"Toute somme ou tout avantage qu'une personne autre que l'employeur attribue à un salarié en contrepartie d'une activité accomplie dans l'intérêt de cette personne constitue une rémunération soumise aux cotisations de sécurité sociale et aux contributions mentionnées aux articles L. 136-1 du présent code, L. 14-10-4 du code de l'action sociale et des familles et 14 de l'ordonnance n° 96-50 du 24 janvier 1996 relative au remboursement de la dette sociale, sous réserve du deuxième alinéa.",
"Lorsque le salarié exerce une activité commerciale ou directement liée à la clientèle pour laquelle l'attribution de sommes ou d'avantages par un tiers à l'employeur est d'usage, la part de ces rémunérations versées au cours d'une année qui n'excède pas 1,5 fois la valeur mensuelle du salaire minimum interprofessionnel de croissance est exonérée des cotisations et contributions d'origine légale ou conventionnelle rendues obligatoires par la loi. Aucune contribution libératoire n'est due sur cette part. La fraction excédant ce plafond reste soumise aux cotisations et contributions mentionnées au premier alinéa.",
"L'exonération du deuxième alinéa ne s'applique pas lorsque le tiers appartient au même groupe que l'employeur au sens de l'article L. 2331-1 du code du travail.",
"Le tiers déclare et verse les cotisations et contributions qui restent dues selon les règles, garanties et sanctions du recouvrement des cotisations du régime général assises sur les salaires. Il informe l'employeur des sommes ou avantages attribués au salarié. Une information exacte et à jour déjà légalement communiquée à l'employeur n'a pas à lui être adressée une seconde fois.",
"Le deuxième alinéa n'est ni applicable ni opposable aux organismes mentionnés aux articles L. 213-1 et L. 752-1 lorsque le tiers et l'employeur ont accompli des actes destinés à éluder tout ou partie des cotisations et contributions sociales. En cas de constat de telles opérations, l'article L. 243-7-2 s'applique à l'employeur.",
"Un décret fixe les modalités d'application du présent article, notamment celles de l'information de l'employeur. Aucune déclaration de contribution libératoire n'est exigée au titre des sommes ou avantages pour lesquels cette contribution est supprimée.",
"Pour les sommes ou avantages attribués avant l'entrée en vigueur de la loi supprimant la contribution libératoire, celle-ci demeure égale à 20 % de la fraction dépassant 15 % de la valeur du salaire minimum interprofessionnel de croissance calculée pour un mois sur la base de la durée légale du travail, dans la limite annuelle de 1,5 fois sa valeur mensuelle. Leur régime antérieur, notamment les exclusions, la répartition des sommes recouvrées entre les attributaires des prélèvements du premier alinéa par arrêté du ministre chargé de la sécurité sociale, les déclarations, le recouvrement, les restitutions, les prescriptions et les recours, est conservé. Le plafond annuel de 1,5 fois la valeur mensuelle s'apprécie sur l'ensemble des sommes et avantages de l'année, sans double emploi. La dispense de seconde information s'applique aux informations à transmettre à compter de cette entrée en vigueur."
], "Réécriture intégrale de l'assujettissement des avantages de tiers. Réforme de fond : suppression prospective de la contribution libératoire de 20 %, avec exonération de la même tranche jusqu'à 1,5 SMIC mensuel, sans report sur les cotisations ordinaires ; suppression de la seconde information identique de l'employeur. Les rémunérations excédentaires, l'exclusion intragroupe et l'abus de droit restent à leur champ.",
"Coordonner les décrets, l'arrêté de répartition et les déclarations pour ne conserver la contribution de 20 % que sur les attributions antérieures. Le seuil de 15 % subsiste uniquement dans cette transition ; le plafond de 1,5 n'est pas doublé l'année de réforme. Aucun transfert des droits sociaux ni rendement financier n'est présumé : l'effet de la recette supprimée sur leurs financeurs reste à documenter. L2331-1 n'est pas fourni ; renvoi existant maintenu, sans lui attribuer le régime de rupture du contrat unique. L243-7-2 a été lu dans le corpus : les garanties et la preuve de l'abus restent distinctes.",
["Contribution libératoire de 20 % sur les avantages de tiers éligibles attribués après l'entrée en vigueur, sans prélèvement de remplacement.", "Déclaration de la contribution supprimée pour les nouvelles attributions et seconde information de l'employeur sur des éléments déjà communiqués."],
"La franchise initiale de 15 % du SMIC mensuel n'est pas perdue : l'exonération est étendue à toute la tranche jusqu'à 1,5 SMIC mensuel. L'exclusion des cotisations ordinaires de cette tranche est maintenue pour les futures attributions éligibles. Les franchises et règles libératoires antérieures restent applicables aux anciennes attributions ; l'intragroupe et l'abus demeurent exclus.")

add(2, ["L'assujettissement aux cotisations de sécurité sociale de la garantie de ressources prévue à l'article L. 243-4 du code de l'action sociale et des familles est régi par les premier et deuxième alinéas de l'article L. 243-5 de ce même code."],
"Réécriture à droit constant : identification directe du code et des deux alinéas compétents. Cette disposition de raccordement ne crée ni prélèvement accessoire ni dossier distinct à supprimer.",
"Attention à l'homonymie : L243-4 et L243-5 sont ici des articles du CASF, hors du corpus fourni. La cible CSS L243-5 fournie dans reference-targets traite de remise des pénalités en procédure collective et ne vérifie pas ce renvoi. Le contenu actuel et la concordance de la garantie de ressources du CASF doivent être contrôlés sur ses textes ; aucune substitution au salaire d'un contrat unique n'est opérée.")

add(3, [
"Lorsqu'un assuré travaille régulièrement et simultanément pour plusieurs employeurs, la part des cotisations due par chacun est calculée au prorata des rémunérations qu'il a versées, dans la limite des maxima fixés en application de l'article L. 241-3.",
"Par dérogation au premier alinéa, la part due par chaque employeur peut être calculée comme si le salarié occupait un emploi à temps partiel dans chacun des établissements qui l'emploient.",
"Pour les catégories de salariés ou assimilés définies par arrêté ministériel et travaillant régulièrement et simultanément pour plusieurs employeurs, les arrêtés peuvent adapter le calcul aux conditions d'exercice de la profession. La part de cotisations due par chaque employeur est alors calculée sur les rémunérations qu'il a versées, soit dans la limite d'un forfait fixé par ces arrêtés, soit en appliquant aux taux des cotisations prévues aux articles L. 241-7 à L. 241-9, L. 242-5, L. 242-7, L. 243-1 et L. 243-2 un abattement forfaitaire fixé par ces arrêtés."
], "Réécriture à droit constant des trois modes de répartition, sans supprimer les options favorables. Le fractionnement empêche de multiplier le plafond à raison de la pluralité d'employeurs ; il a une fonction de calcul essentielle et ne constitue pas une formalité autonome.",
"Préserver régularité, simultanéité, prorata, maxima et faculté alternative de temps partiel. Les renvois historiques à des articles qui n'énoncent pas tous un taux (notamment L241-7 à L241-9, L243-1 et L243-2) sont une imprécision préexistante signalée, sans fabrication de taux. L241-7 à L241-9 ont été lus dans le corpus. Coordonner l'application des ristournes de L242-7 et du plafond de L241-3 sans transformer ce dernier en plafond de toutes les cotisations ni anticiper les paliers de capitalisation.",
benefit="Le calcul alternatif par emploi à temps partiel est conservé sans fermeture aux nouvelles embauches. Les forfaits et abattements professionnels fixés par arrêté restent possibles, avec les mêmes catégories et conditions. La répartition proportionnelle des cotisations plafonnées est maintenue ; aucune augmentation de taux ni suppression des ristournes AT-MP n'est introduite.")

add(4, ["Des décrets peuvent fixer des montants forfaitaires pour calculer les cotisations de sécurité sociale et d'allocations familiales du personnel artistique des entreprises de spectacle qu'ils définissent. Ces montants tiennent compte du plafond des rémunérations soumises à cotisations et sont déterminés selon la catégorie professionnelle et l'importance des rémunérations."],
"Réécriture à droit constant de l'habilitation aux forfaits artistiques. Ce mécanisme de calcul, potentiellement favorable, n'impose ni agrément ni déclaration spéciale dans cet article et reste ouvert aux situations futures.",
"Conserver le caractère facultatif de l'habilitation, le périmètre défini par décret et les deux critères. Ne pas assimiler activité de spectacle et autorisation d'un nouveau CDD ; la forme du contrat n'est pas fixée ici.",
benefit="Les chiffres forfaitaires peuvent alléger le calcul et les cotisations selon les décrets applicables. L'habilitation est entièrement conservée pour les personnels artistiques futurs comme actuels, avec plafond, catégorie professionnelle et niveau de rémunération inchangés.")

add(5, ["La rémunération correspondant aux droits constitués par un salarié sur son compte épargne-temps est exonérée des cotisations de sécurité sociale salariales et patronales lorsqu'il décide de l'affecter à l'une des destinations suivantes : un plan d'épargne pour la retraite collectif prévu aux articles L. 3334-1 à L. 3334-9 et L. 3334-11 à L. 3334-16 du code du travail ; un plan d'épargne retraite d'entreprise collectif prévu aux articles L. 224-13 à L. 224-22 du code monétaire et financier ; le financement de prestations de retraite collectives et obligatoires, définies selon l'une des procédures mentionnées à l'article L. 911-1 du présent code. Cette exonération ne couvre pas les droits correspondant à un abondement en temps ou en argent de l'employeur."],
"Réécriture à droit constant : les trois destinations de l'épargne-temps sont rendues plus lisibles et l'exception patronale est isolée. L'exonération est conservée ; aucune nouvelle pièce ou autorisation n'est créée.",
"Les plages L3334-1 à 9 et 11 à 16 et L224-13 à 22 sont maintenues sans inclure L3334-10. Ne pas confondre cette épargne retraite volontaire et complémentaire avec le transfert conditionnel de cotisations de L241-3. Les notes de 2019 établissent l'entrée en vigueur historique au 1er octobre 2019, pas celle d'une réforme future. Les cibles de ces renvois existants ne figurent pas dans le fichier de contrôle fourni.",
benefit="L'exonération des parts salariale et patronale demeure pour les futures affectations volontaires du compte épargne-temps vers chacun des trois dispositifs : PERCO, PER d'entreprise collectif ou retraite collective obligatoire. L'exclusion des seuls abondements patronaux est maintenue ; aucun gel aux seuls droits déjà acquis n'est introduit.")

add(6, [
"Pour l'application des articles L. 241-2, L. 241-3, L. 241-5 et L. 241-6 du présent code et des articles L. 741-9 et L. 751-10 du code rural et de la pêche maritime, un décret peut fixer des cotisations forfaitaires pour certaines catégories de salariés ou assimilés auxquelles le salaire minimum de croissance ne s'applique pas ou qui relèvent de l'affiliation obligatoire prévue à l'article L. 311-3 du présent code. Ces forfaits ont pour objet de préserver leurs droits aux assurances sociales et ne peuvent dépasser les cotisations applicables au salaire minimum de croissance à temps plein.",
"Un décret peut également fixer des cotisations forfaitaires pour certaines activités occasionnelles ou saisonnières. Lorsque la rémunération atteint au moins 1,5 fois la valeur du plafond mentionné à l'article L. 241-3 correspondant à la durée du travail, la base de calcul doit être au moins égale à 70 % de la rémunération."
], "Réécriture à droit constant des deux habilitations aux forfaits. Maintien du plafond protecteur et du plancher d'assiette des rémunérations élevées, nécessaire pour éviter que le forfait ne vide les droits sociaux de leur base. Le caractère occasionnel ou saisonnier décrit l'activité, sans déterminer la durée de l'emploi.",
"Conserver les alternatives d'éligibilité, le maximum SMIC à temps plein, le seuil inclusif de 1,5 plafond et le minimum de 70 %. Les normes agricoles gardent leur champ, distinct de la première phase privée du transfert vieillesse de L241-3. Aucun nouveau CDD ni taux de cotisation n'est créé.",
benefit="Les deux possibilités de forfait restent ouvertes aux futures catégories et activités éligibles. Le plafond au niveau des cotisations sur le SMIC à temps plein est conservé. Le seuil de 1,5 plafond et l'assiette minimale de 70 % restent limités au second mécanisme ; ils ne restreignent pas le premier.")

add(7, [
"La caisse d'assurance retraite et de la santé au travail détermine chaque année, pour chaque catégorie de risques, le taux de la cotisation d'accidents du travail et de maladies professionnelles selon les règles fixées par décret. Ce décret organise la mutualisation entre entreprises des coûts des maladies professionnelles à effet différé, afin de favoriser l'emploi des salariés âgés et des bénéficiaires de l'obligation d'emploi mentionnée à l'article L. 5212-13 du code du travail.",
"La caisse classe les risques par catégorie. L'employeur ou l'autorité administrative peut contester ce classement devant la juridiction compétente pour le contentieux mentionné au 7° de l'article L. 142-1, qui statue en premier et dernier ressort.",
"Le classement d'un risque peut être modifié à tout moment. L'employeur déclare à la caisse toute circonstance susceptible d'aggraver les risques, sauf si cette circonstance ressort déjà de données exactes, à jour et légalement accessibles à la caisse qui permettent d'en apprécier l'incidence sur ce classement.",
"La caisse compétente notifie à l'employeur ses décisions relatives au taux de cotisation et au classement des risques, par voie électronique selon les modalités fixées par arrêté du ministre chargé de la sécurité sociale. Si leur mise à disposition électronique n'est pas possible, elle les notifie par un autre moyen donnant date certaine à leur réception.",
"Lorsque l'employeur dispose d'un accès effectif aux décisions mises à sa disposition par voie électronique et a été avisé de cette mise à disposition, la notification est réputée faite à la date de consultation et, au plus tard, quinze jours après cette mise à disposition. Ce délai ne court pas avant que l'accès effectif et l'avis soient établis.",
"L'employeur n'est tenu d'accomplir aucune démarche particulière d'adhésion au service pour recevoir ces décisions. Aucune pénalité n'est due pour l'absence d'une telle démarche. La caisse utilise, lorsqu'il permet la notification légale, l'accès sécurisé déjà disponible ; à défaut, elle procède à la notification prévue au quatrième alinéa.",
"Les éléments de calcul de la cotisation prennent en compte le montant couvrant les dépenses supplémentaires des départs en retraite à l'âge fixé en application de l'article L. 351-1-4 et du dispositif mentionné à l'article L. 4163-1 du code du travail. Ces éléments peuvent être modulés par secteur d'activité. Un décret fixe les conditions d'application du présent alinéa.",
"La loi de financement de la sécurité sociale fixe chaque année le montant mentionné à l'alinéa précédent. Elle peut tenir compte des prévisions financières des cinq années à venir et, s'il y a lieu, des recommandations du comité de suivi mentionné à l'article L. 114-4. Un rapport annexé au projet de loi de financement de la sécurité sociale évalue le coût réel, pour la branche accidents du travail et maladies professionnelles, des dépenses supplémentaires des départs à l'âge prévu à l'article L. 351-1-4 et du dispositif mentionné à l'article L. 4163-1 du code du travail.",
"Dans les conditions fixées par décret, la commission des accidents du travail et des maladies professionnelles fixe les éléments de calcul des cotisations conformément aux conditions générales de l'équilibre financier de la branche déterminées par la loi de financement de la sécurité sociale.",
"La délibération de la commission est transmise au ministre chargé de la sécurité sociale avant le 31 janvier de chaque année.",
"Si la commission n'a pas délibéré à cette date ou si les éléments qu'elle a retenus ne respectent pas le neuvième alinéa, l'autorité compétente de l'État les fixe par arrêté.",
"Si les mesures prises en application du présent article ne couvrent pas les charges de gestion, l'équilibre de la branche résultant de la loi de financement de la sécurité sociale est maintenu ou rétabli par un prélèvement sur les excédents financiers ou, à défaut, par une modification des éléments de calcul des cotisations.",
"La dispense de démarche d'adhésion et la suppression de la pénalité s'appliquent à compter de l'entrée en vigueur de la loi qui les institue ; aucun défaut d'adhésion ne peut donner lieu à une nouvelle pénalité après cette date. Les pénalités antérieurement notifiées conservent leur régime, sous réserve de l'application de la loi répressive plus douce aux sanctions non définitives. Les nouvelles modalités de notification s'appliquent aux décisions notifiées à compter de cette date, sans rouvrir un délai de recours expiré. La dispense de déclaration d'une circonstance déjà connue s'applique aux déclarations à effectuer à compter de cette date."
], "Réécriture intégrale du dispositif AT-MP. Réforme de fond : suppression de l'adhésion obligatoire au service et de sa pénalité ; notification de secours par la caisse ; fin des déclarations redondantes d'aggravation déjà documentée. Les taux liés aux risques, la prévention, les retraites pour incapacité et les recours restent financés et contrôlables.",
"Les douze alinéas fonctionnels sont conservés dans leur ordre, avec une transition finale ; le neuvième reste celui de la commission, malgré les sauts internes du XML source. Les limites de pénalité de 1,5 % du plafond mensuel par personne et 10 000 € annuels disparaissent avec cette pénalité pour l'avenir ; le régime antérieur reste celui des décisions anciennes sous réserve de loi plus douce. Coordonner l'arrêté de notification et de pénalité pris sur le fondement des quatrième à sixième alinéas de la source, sans le présenter comme lu ou réécrit. Le délai électronique de quinze jours n'est pas le préavis de rupture. Les alinéas relatifs aux coûts L351-1-4/L4163-1, aux prévisions sur cinq ans et au 31 janvier sont conservés ; aucun transfert vieillesse n'est anticipé.",
["Démarche obligatoire d'adhésion à la notification électronique et pénalité de défaut d'adhésion calculée par personne avec plafond annuel.", "Déclaration séparée d'une aggravation des risques déjà établie par les données exactes et à jour légalement accessibles à la caisse."],
"La mutualisation favorable à l'emploi des salariés âgés et des bénéficiaires de l'obligation d'emploi demeure pour l'avenir. Les prestations et départs anticipés ne sont pas supprimés avec la pénalité d'adhésion. La notification de secours et la preuve d'accès préservent les recours ; les ristournes de L242-7 gardent leur fondement.")

add(8, [
"Les employeurs communiquent le montant total des salaires pour chaque catégorie de risques prévue à l'article L. 242-5. Ils sont dispensés d'une communication distincte lorsque ces montants ressortent, avec la même ventilation, de données exactes, à jour et légalement accessibles à l'organisme destinataire. Seules les données manquantes, modifiées ou contradictoires restent à communiquer.",
"Cette dispense s'applique aux communications exigées à compter de l'entrée en vigueur de la loi qui l'institue, y compris pour une période de rémunération antérieure. Elle ne dispense pas du paiement des cotisations ni des corrections nécessaires."
], "Réforme de fond : suppression de la communication spéciale des masses salariales lorsque leur ventilation par risque est déjà disponible. Réécriture de la règle résiduelle, indispensable à la tarification des risques, sans seconde déclaration de remplacement.",
"La simple présence d'un total global ne suffit pas : la même ventilation par catégorie de L242-5 doit être disponible. Coordonner les circuits déclaratifs existants ; aucun accès à de nouvelles données ni nouveau formulaire n'est autorisé par cette dispense.",
["Communication séparée des masses salariales par risque lorsque cette ventilation est déjà légalement disponible auprès de l'organisme destinataire."])

add(9, [
"Dans les conditions fixées par arrêté interministériel, la caisse d'assurance retraite et de la santé au travail peut accorder une ristourne de cotisation pour tenir compte des mesures de prévention ou de soins prises par l'employeur. Elle peut imposer une cotisation supplémentaire lorsque l'exploitation présente des risques exceptionnels, notamment révélés par une infraction constatée en application de l'article L. 8113-7 du code du travail ou par l'inobservation de mesures de prévention prescrites en application des articles L. 422-1 et L. 422-4 du présent code.",
"La cotisation supplémentaire est due à compter du constat des risques exceptionnels. L'arrêté fixe son taux et sa durée, sans montant forfaitaire minimal obligatoire.",
"L'arrêté mentionné au premier alinéa fixe le pourcentage des cotisations d'accidents du travail et de maladies professionnelles et la part minimale du produit des cotisations supplémentaires à affecter aux ristournes et aux avances prévues à l'article L. 422-5.",
"La décision de la caisse peut être contestée devant la juridiction mentionnée au deuxième alinéa de l'article L. 242-5, compétente pour le contentieux du 7° de l'article L. 142-1.",
"En cas de carence de la caisse, l'autorité compétente de l'État peut statuer. Sa décision peut être contestée devant la même juridiction.",
"La suppression du montant forfaitaire minimal s'applique aux cotisations supplémentaires correspondant aux périodes courant à compter de l'entrée en vigueur de la loi qui la prévoit, y compris lorsqu'elles résultent d'une décision antérieure. Les cotisations correspondant aux périodes antérieures, leurs restitutions, prescriptions et recours conservent leur régime, sous réserve de l'application de la loi répressive plus douce aux sanctions non définitives. Les ristournes et avances restent ouvertes aux futures situations éligibles."
], "Réforme de fond : suppression du montant forfaitaire minimal supplémentaire, sans supprimer la cotisation proportionnelle de prévention des risques exceptionnels. Réécriture des compétences et correction explicite du recours devenu incohérent : L242-5 ne désigne plus de commission de recours, mais la juridiction du contentieux de tarification.",
"Conserver date du constat, taux, durée et deux fractions affectées aux aides de prévention, sans diminuer leurs minima d'affectation. Le renvoi source à une commission de L242-5 est préexistant et erroné ; le renvoi juridictionnel proposé est expressément coordonné avec son deuxième alinéa et L142-1 7°. Coordonner l'arrêté interministériel prévu aux premier à troisième alinéas de L242-7 pour retirer son minimum forfaitaire ; son texte n'est pas fourni et n'est pas déclaré réécrit. L422-1 et L422-4 gardent les injonctions, extensions et exceptions propres aux risques graves. Le financement futur des ristournes ne doit pas être présumé inchangé en montant.",
["Montant forfaitaire minimal obligatoire des cotisations supplémentaires AT-MP pour les périodes futures, y compris sous décision déjà prise."],
"Les ristournes pour prévention ou soins restent attribuables aux futures entreprises éligibles ; les avances de L422-5 et les pourcentages minimaux de financement restent expressément maintenus. La suppression du plancher de cotisation supplémentaire ne supprime ni ces avantages ni leurs créances antérieures.")

add(10, ["Un décret fixe les modalités du passage des règles de tarification des risques d'accidents du travail et de maladies professionnelles propres aux départements du Haut-Rhin, du Bas-Rhin et de la Moselle aux règles correspondantes du régime général des salariés."],
"Réécriture à droit constant de l'habilitation de transition territoriale. Sa suppression sans lecture des mesures locales pourrait fermer des adaptations favorables ; aucune obligation nouvelle ou prélèvement autonome n'est ici imposé.",
"Ne pas confondre tarification AT-MP et assurance maladie complémentaire locale de L242-13. La seule présence de cette habilitation ancienne ne prouve pas que toutes les opérations de transition sont achevées ; aucune caducité n'est affirmée.")

add(11, ["Pour les salariés à temps partiel au sens de l'article L. 3123-1 du code du travail, les cotisations de sécurité sociale calculées en tenant compte du plafond prévu à l'article L. 241-3 bénéficient d'un abattement d'assiette. Cet abattement compense la différence entre les cotisations dues pour chaque salarié et celles qui seraient dues, pour une même durée de travail, si ce salarié travaillait à temps complet."],
"Réécriture à droit constant de l'abattement compensateur. Son objet et son assiette sont conservés, sans nouveau seuil d'horaire ou d'ancienneté ; supprimer cet article augmenterait les charges sur les temps partiels.",
"L3123-1 officiel et sa proposition ont été lus dans le corpus : références hebdomadaire et mensuelle propres au contrat, référence annuelle maintenue à 1 607 heures. Le renvoi existant reste pertinent ; il ne fixe aucun plancher de 24 heures. L241-3 désigne le plafond, non un transfert automatique de cotisations vers la capitalisation. Articuler avec L242-9 et les exclusions précisément maintenues à L242-10.",
benefit="L'abattement d'assiette des cotisations plafonnées est entièrement conservé pour les futurs emplois à temps partiel, sans condition nouvelle de durée minimale ni d'ancienneté. Il continue de compenser la différence à durée de travail identique ; les réductions de formalités ne conditionnent pas son attribution.")

add(12, [
"À chaque échéance de versement des cotisations, l'employeur applique l'abattement d'assiette prévu à l'article L. 242-8.",
"Lorsque des heures complémentaires accomplies au-delà de la durée contractuelle définie à l'article L. 3123-6 du code du travail portent la durée hebdomadaire effective à la durée normale du travail dans l'établissement, l'abattement n'est pas applicable aux seules rémunérations afférentes à la semaine au cours de laquelle cette durée est atteinte. Il demeure applicable aux autres semaines qui remplissent les conditions de l'article L. 242-8 ; l'accomplissement de ces heures ne peut entraîner la perte de l'abattement pour ces autres semaines.",
"Un arrêté interministériel fixe les conditions d'application du présent article.",
"La limitation de la perte de l'abattement s'applique aux cotisations dues au titre des périodes courant à compter de l'entrée en vigueur de la loi qui l'institue. Les cotisations et droits à restitution des périodes antérieures conservent leur régime."
], "Réécriture de l'application à chaque échéance. Réforme de fond favorable : suppression d'une déchéance globale de l'abattement à raison d'heures complémentaires atteignant le temps complet, en limitant son effet à la période concernée ; aucune réduction fictive pour une période effectivement à temps complet.",
"L3123-6 lu dans le corpus maintient l'écrit, la durée garantie et les limites d'heures complémentaires ; il ne crée pas de nouveau CDD. L'arrêté d'application doit isoler les périodes concernées sans supprimer l'abattement des périodes éligibles ni reconstituer une déchéance annuelle. La durée normale de l'établissement n'est pas uniformément remplacée par quarante heures. Pas de prorata d'indemnité de rupture dans cet article.",
["Déchéance de l'abattement sur les autres périodes éligibles au seul motif d'heures complémentaires ayant atteint le temps complet pendant une période distincte."],
"L'abattement de L242-8 est maintenu à chaque échéance et renforcé pour les futures périodes à temps partiel : une période au niveau du temps complet ne ferme plus les autres périodes éligibles. Les anciennes créances de restitution restent protégées ; aucun avantage n'est réservé aux seuls contrats antérieurs.")

add(13, [
"Les articles L. 242-8 et L. 242-9 ne s'appliquent pas :",
"1° Aux salariés ou assimilés dont l'emploi relève de taux, d'assiettes ou de montants spécifiques de cotisations en application des articles L. 242-4-4 et L. 242-3 ;",
"2° Aux salariés ou assimilés dont l'emploi régulier et simultané auprès de plusieurs employeurs entraîne un fractionnement entre ces employeurs du plafond de l'assiette des cotisations de sécurité sociale.",
"Les salariés concernés par des réductions d'horaire ouvrant droit à une indemnisation au titre de l'activité partielle restent exclus de ces dispositions. Les personnels intérimaires des entreprises de travail temporaire peuvent en bénéficier lorsqu'ils remplissent les conditions des articles L. 242-8 et L. 242-9 et ne relèvent pas d'une autre exclusion du présent article.",
"La suppression de l'exclusion propre aux personnels intérimaires s'applique aux cotisations dues au titre des périodes courant à compter de l'entrée en vigueur de la loi qui la prévoit, quelle que soit la date de conclusion du contrat. Elle n'autorise pas la conclusion ou le renouvellement d'un contrat à durée déterminée de droit privé. Les périodes antérieures conservent leur régime."
], "Réforme de fond : suppression de l'exclusion générale des intérimaires du bénéfice de l'abattement de temps partiel. Réécriture des exclusions restantes, destinées à éviter le double emploi avec les forfaits, le fractionnement de plafond ou l'activité partielle indemnisée.",
"Conserver 1°, 2° et le régime distinct d'activité partielle. La mission ne borne pas l'emploi nouveau : les intérimaires en contrat unique peuvent être éligibles, avec leurs garanties d'intermission intactes. L'abattement ne se cumule pas avec le calcul spécifique déjà couvert par 1° ou 2°. Les règlements appliquant l'exclusion catégorielle intérimaire doivent être coordonnés.",
["Exclusion automatique de tous les personnels intérimaires du bénéfice de l'abattement d'assiette des cotisations plafonnées à temps partiel."],
"L'abattement de L242-8 est ouvert aux futurs personnels intérimaires éligibles, sans restriction aux anciens contrats. Les autres forfaits et le fractionnement de plafond demeurent applicables dans leur propre champ ; les exclusions de cumul ne suppriment pas leurs avantages autonomes.")

add(14, [
"Lorsque les données nécessaires au calcul des cotisations n'ont pas été transmises, l'organisme de recouvrement calcule provisoirement les cotisations à partir des dernières données connues ou, si celles-ci ne permettent pas ce calcul, sur une base forfaitaire. Cette base ne fait l'objet d'aucune majoration automatique pour défaut de transmission.",
"Le calcul provisoire tient compte des exonérations dont les conditions sont établies par les données et décisions légalement disponibles. Le défaut de transmission ne justifie pas, à lui seul, d'écarter une exonération.",
"Le cotisant fournit les seules données nécessaires qui ne sont pas déjà exactes, à jour et légalement disponibles auprès de l'organisme. Les cotisations sont régularisées sur la base des données ainsi établies, en tenant compte des exonérations applicables si leurs conditions restent remplies. Aucune pénalité n'est due sur le seul fondement du présent article.",
"Un décret en Conseil d'État fixe les modalités d'application du présent article.",
"La suppression de la majoration automatique de base, de l'exclusion systématique des exonérations et de la pénalité s'applique aux calculs provisoires et régularisations effectués à compter de l'entrée en vigueur de la loi qui la prévoit. Les calculs provisoires antérieurs non définitivement régularisés sont rectifiés selon ces règles. Les cotisations définitivement établies avant cette date et leurs voies de recours conservent leur régime, sous réserve de l'application de la loi répressive plus douce aux sanctions non définitives. Les autres obligations déclaratives et les règles distinctes de lutte contre la fraude demeurent applicables."
], "Réforme de fond : retrait de la base automatiquement majorée, du rejet de toutes les exonérations et de la pénalité propre à cette taxation provisoire. Les informations déjà disponibles sont réemployées. L'estimation puis la régularisation restent possibles pour recouvrer le principal réellement dû, sans assimilation de l'absence de donnée à une fraude.",
"Coordonner le décret de taxation provisoire et les consignes de calcul ; ne pas reconstituer la majoration par un forfait punitif. Les exonérations non encore établies sont prises en compte à la régularisation, sans suppression du droit futur. L'article ne remet pas les cotisations principales ni les sanctions légalement autonomes de fraude ; aucun nouveau taux de pénalité n'est inventé.",
["Majoration automatique de l'assiette provisoire au seul motif de la non-transmission des données de calcul.", "Exclusion de toutes les exonérations lors du calcul provisoire, même lorsque leurs conditions sont déjà établies.", "Pénalité propre à L242-12-1 sur les cotisations finalement dues et nouvelle production des mêmes données déjà accessibles."],
"Toutes les exonérations potentiellement applicables sont préservées pour les situations futures. Celles qui sont démontrées sont intégrées dès le calcul provisoire ; les autres le sont lors de la régularisation si leurs conditions sont remplies. La disparition de la majoration et de la pénalité n'est compensée par aucune augmentation de cotisation ni perte d'avantage.")

add(15, [
"I. - Le régime local d'assurance maladie complémentaire obligatoire des départements du Haut-Rhin, du Bas-Rhin et de la Moselle est financé par :",
"1° Une cotisation des assurés mentionnés aux 1° à 3° du II de l'article L. 325-1, assise sur leurs revenus d'activité retenus dans l'assiette des cotisations définie à l'article L. 242-1. Les employeurs la précomptent au bénéfice du régime local ;",
"2° Une cotisation des assurés mentionnés aux 5° à 11° et à l'avant-dernier alinéa du II de l'article L. 325-1. Elle est assise sur les avantages de vieillesse d'un régime de base, complémentaire ou à la charge de l'employeur, servis selon une législation française ou étrangère, ainsi que sur les allocations et revenus de remplacement mentionnés à l'article L. 131-2. Un décret fixe les modalités de prise en compte des avantages de vieillesse acquis selon une législation étrangère pour calculer la cotisation prélevée sur les avantages servis par un régime français. Les organismes débiteurs français la précomptent, à chaque versement de ces avantages ou allocations, au bénéfice du régime local.",
"Les unions de recouvrement des cotisations de sécurité sociale et d'allocations familiales recouvrent ces cotisations selon les règles, garanties et sanctions applicables aux cotisations du régime général.",
"II. - Le conseil d'administration de l'instance de gestion du régime local détermine les exonérations pour insuffisance de ressources selon les modalités prévues au deuxième alinéa de l'article L. 380-2. Lorsqu'elles sont établies par des données exactes, à jour et légalement accessibles à l'organisme chargé de les appliquer, les conditions d'une exonération ne donnent lieu à aucune nouvelle demande de justificatifs identiques. Seuls les éléments manquants, modifiés ou contradictoires nécessaires à cette appréciation peuvent être demandés.",
"Le conseil fixe, dans la fourchette prévue par décret, les taux de cotisation nécessaires à l'équilibre financier du régime. L'article L. 131-9 ne s'applique pas à ces cotisations.",
"La dispense de justificatifs répétés s'applique aux demandes adressées à compter de l'entrée en vigueur de la loi qui l'institue, y compris pour apprécier une exonération relative à une période antérieure. Elle ne modifie ni les conditions de ressources ni les droits aux prestations."
], "Réécriture de la répartition des cotisants et précomptes à droit constant. Réforme de fond : suppression des justificatifs d'insuffisance de ressources déjà légalement disponibles. La cotisation complémentaire locale conserve sa fonction de financement de prestations spécifiques et n'est pas assimilée à une contribution additionnelle d'IS.",
"Renvoi préexistant à contrôler : le deuxième alinéa du L380-2 actuel, lu dans le corpus, est une condition de faibles revenus professionnels de la cotisation subsidiaire maladie, non les anciennes modalités d'exonération pour insuffisance de ressources. Ce renvoi est maintenu sans réinterprétation ni nouveau seuil ; coordination législative distincte avec le régime d'exonération local à établir. L325-1 est lu en entier : l'avant-dernier alinéa du II vise l'application des 9° et 10° aux retraités du Port autonome de Strasbourg, non la famille énumérée ensuite. Maintenir cette cible, les catégories et les pensions étrangères sous réserve des règles européennes de coordination, non effacées. Les taux CSG et le gel partiel de revalorisation des retraites ne sont pas appliqués à cette cotisation.",
["Nouvelle production de justificatifs de ressources identiques déjà légalement accessibles pour appliquer une exonération du régime local."],
"Les exonérations pour insuffisance de ressources décidées par l'instance locale demeurent ouvertes aux futures situations éligibles, sans nouveau dossier en double. Les prestations complémentaires de L325-1 et les catégories de bénéficiaires sont maintenues. Le renvoi ancien à L380-2 est signalé comme incohérent ; aucun nouveau seuil ni retrait d'exonération n'est déduit du contenu recyclé de cette cible.")

add(16, [
"L'exclusion de l'assiette des cotisations de sécurité sociale prévue au 6° du II de l'article L. 242-1 s'applique aux actions attribuées aux salariés ou aux mandataires sociaux dès lors que ses conditions de fond sont remplies. Elle n'est subordonnée ni à une notification annuelle à l'organisme de recouvrement de l'identité des bénéficiaires, du nombre ou de la valeur des actions, ni à une déclaration de remplacement. Le seul défaut d'une telle notification ne peut rendre l'employeur redevable des cotisations patronales ou salariales sur ces avantages.",
"Cette règle s'applique également lorsque les actions sont attribuées par une société dont le siège est à l'étranger et qui est mère ou filiale de l'entreprise dans laquelle le bénéficiaire exerce son activité. Les obligations déclaratives légalement autonomes et le contrôle des conditions de fond de l'exclusion restent applicables.",
"La suppression de la condition de notification s'applique aux attributions intervenant à compter de l'entrée en vigueur de la loi qui la prévoit. Aucune notification exclusivement fondée sur le présent article ne peut être exigée après cette date, y compris au titre d'une attribution antérieure, et aucune nouvelle déchéance ne peut être prononcée pour son seul défaut. Les cotisations déjà établies avant cette date, leurs restitutions, prescriptions et recours restent régis par les règles alors applicables, sous réserve de l'application de la loi répressive plus douce aux sanctions non définitives."
], "Réforme de fond : suppression effective de la notification annuelle nominative comme condition de l'exclusion d'assiette et de la déchéance totale patronale et salariale qui lui était attachée. Maintien explicite du bénéfice pour les attributions étrangères mère-filiale et des conditions de fond de L242-1 II 6°.",
"Coordonner les formulaires et textes d'application pour ne pas transformer les données identité/nombre/valeur en nouvelle formalité conditionnant le même avantage. L242-1 II 6° distingue l'avantage d'acquisition et la différence du II de CGI 80 bis imposable à la levée d'option : cette différence reste assujettie selon son régime, sans extension implicite de l'exclusion. Les renvois fiscaux existants de la cible ne sont pas remplacés par l'indemnité ordinaire du contrat unique.",
["Notification annuelle obligatoire de l'identité des attributaires et du nombre et de la valeur des actions comme condition d'exclusion d'assiette.", "Déchéance totale de l'exclusion et mise à charge de l'employeur des parts patronales et salariales pour le seul défaut de notification."],
"L'exclusion de L242-1 II 6° est conservée pour les nouvelles attributions remplissant les conditions substantielles, y compris celles d'une mère ou filiale étrangère. Sa déchéance pour défaut de formalité est retirée ; aucun plafond, bénéficiaire ou fait générateur fiscal supplémentaire n'est créé.")

add(17, [
"Lors de chaque paie, l'employeur précompte la contribution du salarié sur la rémunération ou le gain de l'assuré.",
"Le salarié ne peut s'opposer à ce prélèvement. Lorsque l'employeur paie la rémunération après déduction de cette contribution, la retenue vaut acquit de la contribution du salarié dans les rapports entre celui-ci et l'employeur."
], "Réécriture à droit constant : identification de l'employeur chargé du précompte et clarification de l'effet libératoire à l'égard du seul salarié. Le précompte évite un paiement séparé du salarié ; sa suppression créerait une charge et fragiliserait le recouvrement.",
"L'acquit à l'égard du salarié ne dispense pas l'employeur de reverser les sommes à l'organisme compétent. Maintenir l'application à Saint-Pierre-et-Miquelon sous les adaptations nécessaires prévues par l'article 5 de la loi 87-563, mentionné en note ; aucune extension territoriale nouvelle ni transfert de cotisation vieillesse non financé.")

add(18, [
"Sans perte des droits aux prestations correspondantes, l'employeur peut demander que la date limite de paiement des cotisations salariales et patronales afférentes aux rémunérations perçues pendant les douze premiers mois d'activité de l'entreprise par les personnes mentionnées aux 6°, 11°, 12°, 13°, 23° et 25° de l'article L. 311-3 ne soit pas antérieure au treizième mois suivant la date à laquelle elles ont créé ou repris l'entreprise. La même demande permet d'obtenir le paiement par fractions annuelles sur une période n'excédant pas cinq ans, sans seconde demande ; l'employeur peut limiter son choix au seul report. Chaque fraction annuelle est au moins égale à 20 % du total des cotisations dues. Cet étalement ne donne lieu à aucune majoration de retard.",
"Le bénéfice de ces dispositions ne peut être accordé qu'une fois par période de cinq ans au titre d'une création ou d'une reprise d'entreprise.",
"Ces dispositions ne s'appliquent pas à une simple modification des conditions d'exercice de l'activité de l'entreprise.",
"La demande unique s'applique aux demandes présentées à compter de l'entrée en vigueur de la loi qui la prévoit. Une demande déjà en cours peut être complétée par le choix du report seul sans nouveau dossier ; à défaut de ce choix, elle porte sur le report et l'étalement. L'organisme réutilise les pièces exactes, à jour et légalement disponibles et ne peut en exiger une seconde production. Les échéanciers déjà accordés et les droits aux prestations sont conservés."
], "Réforme de fond : fusion des demandes de report et d'étalement, suppression du second dépôt et des pièces déjà disponibles. Réécriture des garanties et limites de l'avantage, sans cotisation supplémentaire ni réduction de prestations.",
"Conserver douze premiers mois, treizième mois, cinq ans de paiement, fraction annuelle minimale de 20 %, intervalle de cinq ans et les six catégories précisément visées de L311-3. Elles comprennent des dirigeants assimilés et des bénéficiaires d'appui, sans créer par elles-mêmes un contrat de travail. La note de la loi de 2003 rend le régime applicable aux entreprises créées ou reprises à compter du 1er janvier 2004 ; la simplification ne rouvre pas les périodes inéligibles. Les conditions d'éligibilité ne sont pas réputées prouvées par une simple demande.",
["Deuxième demande nécessaire pour étaler les cotisations après la demande de report à la création ou reprise d'entreprise.", "Nouvelle production de pièces identiques déjà légalement disponibles pour instruire le report et son étalement."],
"Le report au moins jusqu'au treizième mois, l'étalement jusqu'à cinq ans, l'absence de majoration et le maintien des prestations sont tous conservés pour les nouvelles créations ou reprises éligibles. Le choix du seul report demeure possible. Les échéanciers antérieurs restent acquis ; la demande unique ne modifie ni les catégories ni le minimum de 20 % par fraction.")

add(19, [
"I. - L'employeur dont l'entreprise ne comporte pas d'établissement en France remplit auprès d'un organisme de recouvrement unique, désigné par arrêté du ministre chargé de la sécurité sociale, ses obligations de déclaration et de versement des cotisations et contributions sociales d'origine légale ou conventionnelle dues pour l'emploi de salariés. Le particulier qui n'est pas domicilié en France pour l'impôt sur le revenu peut choisir cette faculté.",
"II. - Les employeurs du I qui sont des particuliers relevant du 3° de l'article L. 133-5-6 ou des entreprises relevant du 1° du même article peuvent utiliser le dispositif prévu à la sous-section 2 de la section 1 du chapitre III bis du livre Ier. L'organisme du I transmet à l'employeur, par voie électronique, les documents qu'il établit, notamment le bulletin de paie.",
"Lorsque la durée de l'emploi et la rémunération ne dépassent pas les plafonds fixés par décret, les cotisations et contributions sociales peuvent être payées d'avance à cet organisme, sur une base forfaitaire tenant compte de la durée totale de la période d'emploi ou du séjour en France. Dans ce cas, les articles L. 133-7 et L. 241-10 ne s'appliquent pas. Pour le contrat unique de droit privé, le plafond de durée s'apprécie sur la durée totale de l'activité ou du séjour en France, sans fractionnement en périodes successives de paiement ; cette durée ne fixe aucun terme au contrat de travail. Le choix du paiement anticipé reste facultatif ; l'employeur peut conserver le régime ordinaire et les avantages auxquels celui-ci ouvre droit.",
"III. - Les déclarations sociales des employeurs du I sont adressées à l'organisme de recouvrement par voie électronique, dans les conditions de l'article L. 133-5. Les cotisations et contributions sont payées par les moyens prévus par décret. L'organisme réutilise les données et pièces exactes, à jour et légalement disponibles ; aucune seconde déclaration ou production des mêmes éléments n'est exigible au titre du présent article, notamment pour passer au dispositif simplifié. Les éléments manquants, modifiés ou contradictoires restent à fournir.",
"IV. - Un décret fixe les modalités d'application du présent article.",
"La dispense de production répétée s'applique aux demandes effectuées à compter de l'entrée en vigueur de la loi qui l'institue, y compris pour une période d'emploi antérieure. L'adaptation de la durée au contrat unique concerne les contrats de droit privé conclus à compter de l'entrée en vigueur de la loi instituant ce contrat ; les contrats antérieurs et les contrats de droit public conservent leur régime propre. La fin de la période de paiement anticipé ne rompt pas le contrat unique et ne dispense pas d'acquitter les cotisations afférentes aux périodes ultérieures."
], "Réforme de fond : suppression des secondes déclarations ou pièces déjà disponibles dans le guichet unique et adaptation de l'option forfaitaire au séjour ou à la période d'activité, sans rétablir un CDD. Réécriture des quatre subdivisions, de l'option des particuliers et des exclusions propres au forfait, préservant l'accès volontaire au régime ordinaire favorable.",
"Conserver entreprise sans établissement et particulier non domicilié fiscalement, 1°/3° de L133-5-6, sous-section et exclusion de L133-7/L241-10 dans la seule option forfaitaire. Le maintien de l'option ordinaire permet les exonérations d'aide à domicile de L241-10 et le recouvrement de L133-7 ; aucun cumul du forfait avec les déductions incompatibles n'est inventé. Les plafonds réglementaires non fournis ne sont ni chiffrés ni supprimés. Les règlements doivent remplacer la durée totale du nouveau contrat par la période couverte, en préservant leurs plafonds et l'éligibilité ; ne pas limiter les aides aux seuls anciens CDD. L'obligation électronique conserve les garanties de L133-5.",
["Seconde déclaration ou production de données et pièces déjà légalement disponibles au guichet unique pour les employeurs sans établissement en France."],
"Le guichet unique, le dispositif simplifié et le paiement anticipé forfaitaire restent accessibles aux futures situations éligibles. Les exonérations et déductions de L241-10 restent utilisables en régime ordinaire : leur non-cumul ne vaut que dans l'option forfaitaire, qui demeure libre. La durée de séjour admissible ne devient pas un terme de l'emploi.")

add(20, [
"Pour les périodes de congés des salariés d'employeurs affiliés aux caisses de congés mentionnées à l'article L. 3141-32 du code du travail, les cotisations et contributions dues aux organismes mentionnés aux articles L. 213-1 et L. 752-4 du présent code sont acquittées comme suit :",
"1° Les employeurs s'acquittent des cotisations mentionnées à l'article L. 813-4 du code de la construction et de l'habitation, des versements mentionnés aux articles L. 2333-64 et L. 2531-2 du code général des collectivités territoriales et des contributions mentionnées à l'article L. 6131-2 du code du travail par des majorations libératoires proportionnelles aux cotisations et contributions correspondantes dues sur les rémunérations qu'ils versent pour l'emploi de leurs salariés. Le taux de ces majorations est fixé par décret. Ce mécanisme ne s'applique à la contribution de l'article L. 6331-6 du code du travail que pour les rémunérations correspondant aux périodes de travail antérieures à l'entrée en vigueur de la loi instituant le contrat unique, et à celle de l'article L. 6242-1 du même code que pour les années civiles antérieures au 1er janvier de l'année suivant l'entrée en vigueur de la loi supprimant cette dernière contribution. Aucune majoration n'est due au titre de ces contributions pour les périodes ou années où elles sont supprimées ;",
"2° Pour les cotisations de sécurité sociale et les contributions mentionnées à l'article L. 136-2 du présent code, à l'article 14 de l'ordonnance n° 96-50 du 24 janvier 1996 relative au remboursement de la dette sociale et au 1° de l'article L. 14-10-4 du code de l'action sociale et des familles, les caisses de congés versent, avant la fin du mois au cours duquel elles encaissent les cotisations, un montant égal au produit des cotisations encaissées par un taux fixé par décret en fonction des taux de cotisations et contributions en vigueur. Ce versement est, s'il y a lieu, ajusté selon les modalités fixées par décret en fonction des indemnités de congés payés effectivement versées.",
"Le 2° ne s'applique pas aux employeurs mentionnés à l'article L. 5424-22 du code du travail.",
"Les majorations relatives aux contributions supprimées restent établies, recouvrées, régularisées ou restituées pour les périodes ou années antérieures selon les règles alors applicables, avec leurs exonérations, exclusions, prescriptions et recours. La suppression ne réduit ni les indemnités de congés acquises ni les droits à la formation, les aides à l'apprentissage ou la créance favorable maintenue en lien avec l'article L. 6242-1 du code du travail. Aucun prélèvement équivalent ne peut être perçu au seul motif que l'emploi relève du contrat unique."
], "Réforme de fond coordonnée : retrait effectif des majorations libératoires correspondant au CPF-CDD et à la contribution supplémentaire à l'apprentissage pour leurs périodes de suppression respectives. Les deux circuits de financement des congés sont réécrits intégralement et conservés pour les autres cotisations ; la caisse ne recouvre pas indirectement une contribution supprimée.",
"L6331-6 proposé supprime le 1 % pour les périodes de travail futures, même sous ancien CDD ; L6242-1 proposé supprime la CSA à partir du 1er janvier suivant sa loi, avec maintien d'une créance favorable : les deux dates ne se confondent pas. Coordonner les taux réglementaires de majoration sans chiffrage inventé et les liquidations d'années anciennes. L6131-2 a été lu dans le corpus : taxe d'apprentissage et formation professionnelle ordinaires distinctes restent dans le 1°. L3141-32 et L5424-22 ont été lus : affiliation aux caisses et exception du spectacle sont maintenues, sans recréer un contrat de mission à terme. L136-2 vise une assiette CSG et non un taux global à substituer aux taux des autres contributions. Les notes d'entrée en vigueur de 2021/2022 ne datent pas ces suppressions futures.",
["Majorations libératoires portant sur la contribution CPF-CDD pour les périodes de travail postérieures à son extinction, y compris sous ancien contrat.", "Majorations portant sur la contribution supplémentaire à l'apprentissage pour les années civiles commençant après sa suppression coordonnée."],
"La disparition des deux majorations suit celle des contributions : aucun transfert vers les autres cotisations ni aucune perte de congés ou de CPF n'est prévu. Les exclusions et restitutions antérieures restent valables. Les aides d'apprentissage et la créance favorable rattachée au quotient de L6242-1 restent ouvertes aux situations futures selon leurs textes, sans maintenir la CSA.")

add(21, ["Les sections 2 à 5 du présent chapitre, le chapitre IV du titre IV du présent livre ainsi que les articles L. 133-4-10 et L. 374-1 du présent code régissent le recouvrement des cotisations dues sur les revenus de remplacement mentionnés à la section 1 du chapitre Ier du titre III du livre Ier, sous réserve des adaptations fixées par voie réglementaire."],
"Réécriture à droit constant de l'énumération des règles de recouvrement. Le regroupement de règles communes évite une procédure parallèle ; aucune obligation accessoire autonome n'est identifiée dans cet article de renvoi.",
"Conserver sections 2 à 5, chapitre IV et les deux articles particuliers, sans leur substituer le régime des revenus d'activité. Les contrôles engagés depuis le 1er janvier 2017 restent couverts selon la note source. La baisse de CSG salariale privée et l'IS à la distribution n'étendent pas leurs taux aux revenus de remplacement.")

add(22, [
"Lorsqu'une société, une personne morale ou un autre groupement a fait l'objet d'une verbalisation pour travail dissimulé, le président du tribunal judiciaire peut déclarer son dirigeant solidairement responsable du paiement des cotisations, contributions et sanctions pécuniaires dues par ce groupement. Cette responsabilité suppose que le dirigeant soit responsable de manœuvres frauduleuses ou d'une inobservation grave et répétée des obligations sociales ayant rendu impossible le recouvrement de ces sommes.",
"Le directeur de l'organisme créancier assigne à cette fin le dirigeant devant le président du tribunal judiciaire du lieu du siège social.",
"Le présent article s'applique à toute personne qui exerce, en droit ou en fait, directement ou indirectement, la direction effective de la société, de la personne morale ou du groupement.",
"Les voies de recours contre la décision du président du tribunal judiciaire n'empêchent pas le directeur de l'organisme créancier de prendre contre le dirigeant des mesures conservatoires destinées à préserver le recouvrement de la créance sociale."
], "Réécriture à droit constant des conditions cumulatives de la solidarité judiciaire et des pouvoirs conservatoires. La protection contre la fraude au travail dissimulé justifie le maintien de ce dispositif, qui ne rend pas tout dirigeant automatiquement débiteur.",
"Conserver verbalisation, imputabilité au dirigeant, fraude ou inobservation à la fois grave et répétée, et impossibilité causale de recouvrement. Maintenir l'assignation, le ressort du siège social et les recours ; les mesures conservatoires restent soumises à leurs conditions légales propres. La note de 2019 porte sur la compétence judiciaire applicable au 1er janvier 2020, non sur une nouvelle sanction.")

add(23, [
"À compter de leur exigibilité, le paiement des cotisations est garanti par un privilège sur les biens meubles du débiteur, pour la durée et selon les modalités fixées par décret en Conseil d'État. Ce privilège prend rang concurremment avec celui des salariés établi par l'article 2331 du code civil et les articles L. 625-7 et L. 625-8 du code de commerce. Il ne garantit pas les majorations ni les pénalités de retard.",
"L'hypothèque légale garantissant, sur le seul fondement du présent article, les cotisations, majorations et pénalités de retard est supprimée pour les créances devenant exigibles à compter de l'entrée en vigueur de la loi qui la supprime. Les sûretés et mesures conservatoires fondées sur d'autres dispositions restent soumises à leur régime propre.",
"La limitation du privilège aux cotisations s'applique aux créances devenant exigibles à compter de cette même date. Pour les créances exigibles auparavant, le privilège et l'hypothèque légale, instituée à compter du 1er janvier 1956, conservent leur régime antérieur de constitution, de publicité, de rang, de renouvellement, de réalisation et de radiation, avec les contestations et prescriptions correspondantes. La suppression des garanties sur les nouvelles majorations et pénalités n'en remet pas le principal ni n'étend une sûreté ancienne à une créance nouvelle."
], "Réforme de fond : suppression de l'hypothèque légale sociale pour les nouvelles créances et retrait des accessoires punitifs du privilège mobilier futur. Le privilège du principal des cotisations est maintenu pour protéger leur recouvrement ; les sûretés antérieures sont préservées. La phrase de rang est clarifiée explicitement.",
"La source comporte le segment fautif « concurremment avec et celui » : retrait du seul « et » pour restituer la comparaison de rang, sans modifier ce rang. La référence source à l'article 2331 du code civil doit être vérifiée dans la version applicable depuis la réforme des sûretés ; le code civil et les articles commerciaux ne sont pas fournis, leur contenu n'est pas présumé vérifié. Coordonner le décret de privilège et les formalités de publicité foncière pour les seules créances nouvelles. Le 1er janvier 1956 demeure la date historique de l'hypothèque ancienne, non celle de la suppression. La note mentionne la loi 2025-1403 au 31 décembre alors que d'autres sources du lot la datent du 30 : divergence documentaire signalée, non utilisée pour dater la réforme. Les remises de CSS L243-5 en procédure collective restent autonomes.",
["Hypothèque légale automatique de L243-4 garantissant les cotisations et leurs accessoires pour les créances devenant exigibles après la réforme.", "Garantie par privilège mobilier des nouvelles majorations et pénalités de retard, le privilège restant limité aux cotisations principales."],
"La libération des nouvelles créances de l'hypothèque légale et le retrait des pénalités du privilège allègent les sûretés sans créer de taxe ni réduire d'exonération. Les remises légales de pénalités en procédure collective, les recours et la radiation des sûretés anciennes restent à leur champ propre.")

# Les contrôles portent sur la vue fournie, et ne traitent jamais la proposition
# d'une cible comme du droit positif.
CONTEXT = {
0:"La correction interorganismes de droits sociaux après redressement n'est pas une rupture de contrat.",
1:"L'assujettissement et l'exonération des avantages versés par un tiers rémunèrent une activité ; ils ne fixent pas une indemnité de rupture.",
2:"La garantie de ressources du CASF est une prestation ou rémunération de son régime propre, non un licenciement privé.",
3:"Le partage des cotisations entre employeurs simultanés dépend des rémunérations et plafonds, non de l'ancienneté chez un seul employeur.",
5:"L'affectation volontaire de droits de compte épargne-temps à la retraite ne constitue pas la liquidation d'une indemnité de rupture.",
6:"Les forfaits des activités occasionnelles ou saisonnières caractérisent l'activité et l'affiliation, sans autoriser un terme d'emploi.",
7:"La tarification annuelle AT-MP et la notification à l'employeur sont distinctes de la notification de rupture à un salarié.",
8:"La communication de salaires par risque renseigne le calcul AT-MP ; elle ne détermine aucune procédure de rupture individuelle.",
9:"Les ristournes et suppléments AT-MP répondent aux mesures de prévention et aux risques, sans condition de durée de contrat.",
11:"L'abattement de cotisations plafonnées est attaché au temps partiel effectif, sans seuil d'ancienneté.",
12:"La perte limitée de l'abattement vise les seules périodes atteignant le temps complet ; elle ne règle pas la rupture de l'emploi.",
13:"La suppression de l'exclusion des intérimaires ouvre un abattement de cotisations, sans changer les garanties de leur emploi.",
15:"Le financement de l'assurance maladie locale vise aussi des agents publics, des retraités et des revenus de remplacement.",
16:"L'exclusion d'assiette des actions et la suppression de leur notification annuelle sont indépendantes du mode de rupture du contrat.",
18:"Le report de cotisations de création ou reprise vise les catégories de L311-3, dont des dirigeants assimilés sans contrat de travail.",
19:"Le paiement forfaitaire de l'employeur étranger porte sur une période d'activité ou de séjour, et non un terme nouveau du contrat unique.",
20:"Les cotisations sur les congés et leurs caisses n'ont pas pour objet l'indemnité ordinaire de rupture ; les congés acquis restent dus."
}

COMMON = {
'L1234-1':"Aucun renvoi direct à L1234-1 n'est ajouté. Sa proposition réserve aux nouveaux contrats les quinze jours calendaires et conserve le régime des anciens ; cette durée n'est pas importée dans le calcul social présent. Le départ du délai suit le lendemain de la présentation ou réception de la notification écrite selon L1234-3 proposé, sans supprimer procédures collectives ni autorisations distinctes.",
'L1221-2':"La source officielle admet encore des CDD ; sa proposition n'admet que le contrat unique à durée indéterminée pour les nouvelles relations privées et conserve les anciens contrats. Le présent texte ne crée ni CDD spécial ni fin automatique de l'emploi par mission, formation, congé ou période déclarée ; il ne transforme pas les agents publics en salariés privés.",
'L1234-9':"Aucun renvoi direct à l'indemnité ordinaire n'est nécessaire ici. Dans la proposition de L1234-9, le seuil d'un an se mesure à la fin effective, préavis inclus ; 0,20 mois porte ensuite sur toute l'ancienneté avec fractions en mois complets, plafond de six mois et initiative patronale, sous réserve de l'exception de faute grave que cette cible conserve. Le seuil ancien de huit mois, les composantes anciennes et les indemnités spéciales restent distincts, sans effet sur l'assiette ou l'avantage ici rédigé."
}

SPEC = {
(0,'L213-1'):"L213-1 I 8° charge les URSSAF de la cohérence et de la correction des déclarations ; sa proposition dispense déjà de refaire la même correction. La transmission de L242-1-3 complète cette compétence au profit des organismes de droits ; elle ne la transforme pas en compétence de liquidation universelle ni n'étend l'accès aux données agricoles.",
(1,'L213-1'):"L213-1 I 1°, 4° et 8° organise le recouvrement et les vérifications, non le fait générateur des avantages de tiers. L'exonération nouvelle de L242-1-4 exclut sa tranche du recouvrement futur sans reporter la contribution supprimée sur un autre poste ; les contrôles de fraude et les anciennes créances restent dans leur champ.",
(2,'L243-5'):"La cible fournie est L243-5 du CSS : remise des pénalités et frais à l'ouverture d'une sauvegarde, d'un redressement ou d'une liquidation, sauf travail dissimulé. L242-2 vise expressément les deux premiers alinéas de L243-5 du CASF, absent du dossier. Homonymie inapplicable : ce texte fourni ne valide pas le renvoi et aucune règle de contrat unique ou de seuil de rupture n'en est tirée.",
(3,'L242-7'):"L242-7 autorise ristournes de prévention et suppléments pour risque exceptionnel, et non un plafond par employeur. L'abattement professionnel de L242-3 reste distinct ; la suppression proposée du minimum forfaitaire de supplément ne supprime ni ristournes ni pluralité d'employeurs et doit être répercutée dans les arrêtés professionnels concernés.",
(3,'L241-3'):"Le premier alinéa officiel de L241-3 porte le plafond salarial annuel non décroissant, alors que son troisième prévoit aussi des cotisations déplafonnées. Le prorata de L242-3 ne rend pas toutes les cotisations plafonnées. La capitalisation de la proposition demeure conditionnée et n'est pas déclenchée par le seul fractionnement entre employeurs.",
(3,'L242-5'):"L242-5 détermine les taux AT-MP par risque et permet les classements contestables ; le renvoi de L242-3 vise ces cotisations dans un forfait professionnel, non la notification de rupture. La suppression de la pénalité d'adhésion proposée dans le présent lot n'affecte pas ce fondement ni les ristournes et abattements.",
(6,'L241-5'):"L241-5 met les cotisations AT-MP à la charge exclusive de l'employeur et interdit l'exonération totale, tout en permettant l'imputation plafonnée des réductions citées. Le forfait de L242-4-4 conserve ses limites propres ; le renvoi ne supprime ni les réductions existantes ni la protection AT-MP et ne met aucune cotisation patronale à charge du salarié.",
(6,'L311-3'):"L311-3 énumère les affiliations de salariés et assimilés, y compris dirigeants, personnes occasionnelles et agents publics ; ce n'est pas une liste de CDD autorisés. La condition alternative d'affiliation de L242-4-4 et les forfaits restent ouverts ; aucune requalification générale en contrat privé n'est déduite de cette énumération.",
(6,'L241-3'):"Le renvoi au plafond de L241-3 sert à fixer le seuil de 1,5 plafond ajusté à la durée du travail ; à partir de ce seuil, le forfait occasionnel garde une base d'au moins 70 %. Il ne s'agit ni d'un seuil d'ancienneté ni du taux de transfert vers la capitalisation, dont les conditions préalables ne sont pas remplies par ce renvoi.",
(7,'L4163-1'):"L4163-1 déclare les expositions au-delà des seuils après protections collectives et individuelles, avec confidentialité et données des utilisateurs d'intérim. Le renvoi de L242-5 couvre le coût du compte professionnel de prévention ; les informations de santé et les droits demeurent et aucune déclaration d'exposition n'est supprimée avec la pénalité d'adhésion à la notification tarifaire.",
(7,'L142-1'):"Le 7° de L142-1 vise explicitement taux AT-MP, ristournes et cotisations supplémentaires. Le deuxième alinéa de L242-5 conserve cette juridiction de tarification et le premier et dernier ressort ; la suppression de la seule pénalité d'adhésion ne supprime pas les recours sur taux et classement.",
(7,'L114-4'):"L114-4 organise l'avis annuel et les recommandations du comité de suivi, notamment les départs anticipés, la pénibilité et la solidarité. L242-5 peut tenir compte de ces recommandations pour ses prévisions de cinq ans ; il ne donne pas au comité le pouvoir de fixer une nouvelle cotisation ni de tenir les paliers de capitalisation pour financés.",
(7,'L351-1-4'):"L351-1-4 conserve retraite à soixante ans pour l'incapacité qualifiée, taux plein et baisse de deux ans sous autres conditions, avec exceptions à la preuve d'exposition pour certaines maladies. L242-5 finance les dépenses correspondantes ; la suppression de formalités tarifaires ne modifie ni ces âges, ni les exceptions, ni les conditions médicales des pensions futures.",
(8,'L242-5'):"Le classement des catégories de risques et le taux annuel de L242-5 nécessitent la ventilation salariale conservée à L242-6. La dispense ne porte que sur une seconde communication de la même ventilation légalement disponible ; elle ne supprime ni la tarification, ni les corrections, ni le recours de l'employeur contre le classement.",
(9,'L422-4'):"L422-4 fonde les mesures justifiées de prévention, l'inspection, l'homologation et les cas de supplément sans nouvelle injonction, notamment récidive ou situations graves. Ces protections sont maintenues ; la suppression du minimum forfaitaire à L242-7 n'abolit pas le supplément pour risque exceptionnel. L'ancien renvoi L611-10 de cette cible n'est pas mis à jour implicitement.",
(9,'L422-1'):"L422-1 règle l'extension territoriale et le constat des mesures générales de prévention. Ce fondement demeure visé pour caractériser l'inobservation justifiant un supplément ; aucune formalité de rupture individuelle ou ancienneté d'un salarié ne peut remplacer l'examen des risques. Ses références historiques au code du travail restent à coordonner hors du présent lot.",
(9,'L242-5'):"L242-5 actuel ne contient pas la commission de recours annoncée par L242-7 : il désigne au deuxième alinéa la juridiction compétente au titre de L142-1 7°. Le texte proposé corrige expressément les quatrième et cinquième alinéas de L242-7 vers cette juridiction ; la commission nationale de fixation des éléments de taux n'est pas une commission de recours.",
(11,'L241-3'):"Le plafond de L241-3, et non ses cotisations déplafonnées, est l'objet de l'abattement de L242-8. Le maintien de sa revalorisation et de son plancher annuel demeure ; le transfert progressif proposé vers la capitalisation ne permet ni de supprimer l'abattement ni de multiplier les droits sur une même cotisation.",
(12,'L242-8'):"L242-8 compense la différence de cotisations plafonnées pour une durée identique à temps complet. L242-9 continue de l'appliquer à chaque échéance ; le retrait ne frappe que la période qui atteint le temps complet, et non les autres périodes éligibles. Aucun taux de majoration d'heures supplémentaires n'est substitué à cet abattement.",
(13,'L242-9'):"L242-9 prévoit l'abattement à chaque échéance et son effet quand les heures complémentaires atteignent la durée normale de l'établissement. Les intérimaires admis par L242-10 restent soumis à ces conditions réécrites : ni abattement fictif sur du temps complet, ni perte générale des autres périodes éligibles.",
(13,'L242-8'):"L242-8 définit l'avantage compensateur pour les cotisations plafonnées à temps partiel. La suppression de l'exclusion des intérimaires dans L242-10 ouvre cet avantage aux périodes futures éligibles ; elle ne modifie pas sa formule ni les exclusions pour forfait spécifique, fractionnement multiemployeur ou activité partielle indemnisée.",
(15,'L325-1'):"L325-1 II 1° à 3° couvre les actifs dont des agents publics ; 5° à 11° vise remplacement, invalidité et retraites avec conditions territoriales ou d'affiliation. L'avant-dernier alinéa du II concerne les anciens salariés du Port autonome de Strasbourg. L242-13 conserve exactement ces groupes et ne prend pas les membres de famille comme assujettis nouveaux au seul motif d'être bénéficiaires.",
(15,'L242-1'):"L242-1 I définit l'assiette d'activité et son II les exclusions, dont épargne, protection complémentaire et indemnités de rupture. L242-13 I 1° reprend cette assiette, sans neutraliser les exclusions ni appliquer le taux proposé de CSG privée à la cotisation locale. La suppression de justificatifs d'exonération ne supprime pas ces avantages d'assiette.",
(16,'L242-1'):"Le 6° du II de L242-1 exclut les avantages du I des articles 80 bis et 80 quaterdecies, mais assujettit la différence définie au II de 80 bis à la levée d'option. L242-14 supprime la condition de notification pour les actions éligibles ; il ne modifie ni cette différence assujettie ni les conditions fiscales de fond. Le 7° relatif aux indemnités de rupture reste distinct.",
(18,'L311-3'):"L243-1-1 vise seulement les 6°, 11°, 12°, 13°, 23° et 25° de L311-3 : gérants et dirigeants assimilés, membres ou dirigeants de coopératives et bénéficiaires d'appui. Ce renvoi précis est conservé avec les douze premiers mois, le treizième mois et l'intervalle de cinq ans ; l'assimilation sociale n'impose pas un contrat unique à un mandat social.",
(19,'L133-5'):"L133-5 organise la transmission électronique, l'accusé de réception et la dispense des autres formalités préalables au télérèglement après inscription. L243-1-2 III conserve cette voie et n'ajoute pas de second circuit pour les mêmes données ; les garanties de preuve de dépôt ne sont pas supprimées avec les doubles pièces.",
(19,'L133-7'):"L133-7 règle le recouvrement des emplois à domicile et les délégations aux organismes de retraite et assureurs, avec branche agricole distincte. Son exclusion reste limitée au paiement anticipé forfaitaire de L243-1-2 II ; les employeurs éligibles peuvent rester au régime ordinaire, sans assimiler un séjour court à un contrat à terme.",
(19,'L133-5-6'):"L243-1-2 II renvoie au seul 1° de L133-5-6 pour les entreprises et au 3° pour les particuliers, non à tous les neuf cas. Le dispositif reste facultatif et ne ferme pas les avantages futurs ; les entreprises agricoles et du spectacle exclues du 1° ne deviennent pas éligibles par la seule suppression des nouvelles embauches en CDD.",
(19,'L241-10'):"L241-10 conserve exonérations d'aide à domicile, déductions de 2 € ou 3,70 €, protection des agents territoriaux et conditions des structures. La non-application à L243-1-2 reste celle du seul forfait anticipé choisi ; le régime ordinaire reste accessible. La proposition de L241-10 préserve remplacements futurs en contrat unique et contrats publics, sans recréer de CDD privé.",
(20,'L6331-6'):"L6331-6 officiel fixe le CPF-CDD à 1 % avec exemptions d'alternance, de formation et saisonnières ; sa proposition le supprime pour les périodes de travail futures même sous ancien CDD. L243-1-3 1° interdit donc toute majoration correspondante pour ces périodes, tout en conservant exclusions, recouvrement et restitutions des périodes antérieures et les droits CPF.",
(20,'L6242-1'):"L6242-1 proposé supprime la CSA à partir du 1er janvier suivant la loi tout en conservant la créance liée au quotient de 5 % et ses catégories, y compris après formation au sein du contrat unique. L243-1-3 cesse ses majorations pour ces années, sans avancer cette date au jour de suppression du CPF-CDD ni effacer les années anciennes et leurs exonérations.",
(20,'L136-2'):"L136-2 fixe notamment la réduction d'assiette de 1,75 % sous quatre plafonds et les assiettes forfaitaires de CSG, non le taux de toute contribution sur congés. L243-1-3 2° conserve le circuit des caisses et ses ajustements ; le taux réglementaire doit respecter les contributions effectivement dues sans transformer la baisse de CSG privée en taux des autres prélèvements.",
(20,'L213-1'):"L213-1 I attribue le recouvrement et sa proposition exclut déjà le CPF-CDD sur les périodes futures ; L243-1-3 ferme le canal indirect des majorations de congés pour ce même prélèvement. Les autres missions de recouvrement et les créances anciennes demeurent, sans neutraliser les congés acquis ou les régimes du spectacle.",
}

targets_by_key = R['targets']
for i,a in enumerate(A):
    keys=R['requirements'][a['code_id']+'|'+a['source_id']]
    if keys:
        checks=[]
        for key in keys:
            t=targets_by_key[key]
            n=t['number']
            if n in COMMON:
                assessment=CONTEXT[i]+' '+COMMON[n]
            else:
                assessment=SPEC[(i,n)]
            checks.append(dict(target_key=key,view_sha256=t['view_sha256'],assessment=assessment))
        a['reference_checks']=checks

assert len(A)==len(S)==24
Path('answer.json').write_text(json.dumps(A,ensure_ascii=False,indent=2)+'\n')
